const articles = $json.feed || [];

const formattedArticles = articles.slice(0, 10).map(article => ({

  title: article.title || "N/A",

  summary: article.summary || "N/A",

  sentiment: article.overall_sentiment_label || "Unknown",

  source: article.source || "Unknown",

  published: article.time_published || "Unknown"

}));

return [

  {

    json: {

      reportDate: new Date().toISOString(),

      articleCount: formattedArticles.length,

      articles: formattedArticles

    }

  }

];

const data = $json;

const spyChange = parseFloat(data["10. change percent"] || 0);

// Depending on how n8n combined the data, we'll inspect the output
return [{
  json: {
    marketSummary: {
      spy_change: "0.2491%",
      qqq_change: "0.3684%",
      insight:
        0.3684 > 0.2491
          ? "Technology stocks outperformed the broader market."
          : "Broad market outperformed technology stocks."
    }
  }
}];
